import json,subprocess,unittest
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]

class RatWorkspaceModel(unittest.TestCase):
 def test_partial_personal_effort_is_counted_without_hiding_the_unfilled_slot(self):
  x=self.run_js("const a=W.save(M.initial(),[],{content:'含TL的计划',month:'2026-11',owner:'测试负责人、测试人员甲、测试人员乙',effort:'/3/10'},ctx);const entry=W.entries(a.intake,'2026-11')[0];console.log(JSON.stringify({days:entry.days,unknown:entry.unknown,raw:entry.allocations[0].effort}))")
  self.assertEqual(x,{'days':13,'unknown':True,'raw':'/3/10'})
 def run_js(self,body):
  script="""globalThis.window={};await import('./src/fe-board/intake/model.js');await import('./src/fe-board/intake/rat-model.js');await import('./src/fe-board/intake/workspace-model.js');
const M=window.LubanIntake,R=window.LubanRat,W=window.LubanRatWorkspace;let n=0;
const ctx={actor:{kind:'creator',id:'creator',name:'维护人'},at:'2026-11-06T02:00:00Z',today:'2026-11-06',modules:['系统','规划','控制'],uid:()=>String(++n),newFE:({id,fields,tasks})=>({id,title:fields.title,stage:0,modules:[...new Set(tasks.flatMap(t=>t.modules||[t.module]))],owner:tasks.map(t=>t.owner).join('、'),history:[],phaseDates:{development:{actualStart:''}}})};
function base(){let a=W.save(M.initial(),[],{content:'持续工作',source:'内部迭代',modules:['系统','规划'],month:'2026-11',owner:'甲',effort:'10'},ctx);a=W.toggle(a.intake,a.records,{demandId:a.demandId,month:'2026-11',checked:true},ctx);a.records[0].stage=1;a.records[0].history=[{text:'开发中'}];a.records[0].phaseDates.development.actualStart='2026-11-04';return a;}
"""+body
  p=subprocess.run(['node','--input-type=module','-e',script],cwd=ROOT,text=True,capture_output=True)
  self.assertEqual(p.returncode,0,p.stderr);return json.loads(p.stdout)
 def test_carry_is_one_monthly_relation_with_same_identity_and_fresh_effort(self):
  x=self.run_js("const a=base(),before=JSON.stringify(a.intake.tasks[0]);const b=W.prepareMonth(a.intake,a.records,'2026-12',ctx),t=b.intake.tasks.find(t=>t.month==='2026-12'),s=R.resources(b.intake,'2026-12','all');console.log(JSON.stringify({records:b.records.length,demand:t.demandId===a.intake.demands[0].id,fe:t.feId===a.records[0].id,plans:b.intake.tasks.length,newReview:t.review,effort:t.effort,allocations:t.allocations.map(x=>x.effort),oldSame:JSON.stringify(b.intake.tasks[0])===before,inputSame:JSON.stringify(a.intake.tasks[0])===before,people:s.people.map(p=>({name:p.name,days:p.days,unknown:p.unknown})),known:s.knownRows,unknown:s.unknownRows}))")
  self.assertEqual(x,{'records':1,'demand':True,'fe':True,'plans':2,'newReview':None,'effort':'','allocations':[''],'oldSame':True,'inputSame':True,'people':[{'name':'甲','days':0,'unknown':1}],'known':0,'unknown':1})
 def test_preparing_month_twice_does_not_duplicate_work_or_reset_review(self):
  x=self.run_js("const a=base();let b=W.prepareMonth(a.intake,a.records,'2026-12',ctx);b=W.toggle(b.intake,b.records,{demandId:b.intake.demands[0].id,month:'2026-12',checked:true},ctx);const before=JSON.stringify(b),again=W.prepareMonth(b.intake,b.records,'2026-12',ctx);console.log(JSON.stringify({same:JSON.stringify(again)===before,records:again.records.length,tasks:again.intake.tasks.length,ids:new Set(again.intake.tasks.map(t=>t.feId)).size}))")
  self.assertEqual(x,{'same':True,'records':1,'tasks':2,'ids':1})
 def test_unfinished_work_still_carries_after_an_unreviewed_month_without_duplicates(self):
  x=self.run_js("const a=base(),id=a.records[0].id;let b=W.prepareMonth(a.intake,a.records,'2026-12',ctx);const december=JSON.stringify(b.intake.tasks.find(t=>t.month==='2026-12'));b=W.prepareMonth(b.intake,b.records,'2027-01',ctx);b=W.prepareMonth(b.intake,b.records,'2027-01',ctx);const january=b.intake.tasks.find(t=>t.month==='2027-01');console.log(JSON.stringify({records:b.records.length,demands:b.intake.demands.length,tasks:b.intake.tasks.length,id:january.feId===id,review:january.review,owners:january.allocations.map(a=>a.owner),effort:january.allocations.map(a=>a.effort),modules:january.modules,december:JSON.stringify(b.intake.tasks.find(t=>t.month==='2026-12'))===december,november:b.intake.tasks[0].review.result}))")
  self.assertEqual(x,{'records':1,'demands':1,'tasks':3,'id':True,'review':None,'owners':['甲'],'effort':[''],'modules':['系统','规划'],'december':True,'november':'passed'})
 def test_december_review_keeps_november_review_and_execution_facts(self):
  x=self.run_js("const a=base(),old=JSON.stringify(a.intake.tasks[0]);let b=W.prepareMonth(a.intake,a.records,'2026-12',ctx);b=W.toggle(b.intake,b.records,{demandId:b.intake.demands[0].id,month:'2026-12',checked:true},ctx);console.log(JSON.stringify({old:JSON.stringify(b.intake.tasks[0])===old,months:b.records[0].ratMonths,id:b.records[0].id===a.records[0].id,stage:b.records[0].stage,history:b.records[0].history,date:b.records[0].phaseDates.development.actualStart}))")
  self.assertEqual(x,{'old':True,'months':['2026-11','2026-12'],'id':True,'stage':1,'history':[{'text':'开发中'}],'date':'2026-11-04'})
 def test_withdraw_and_restore_preserve_fe_id_history_and_stage(self):
  x=self.run_js("const a=base(),id=a.records[0].id;a.records[0].stage=0;let b=W.toggle(a.intake,a.records,{demandId:a.intake.demands[0].id,month:'2026-11',checked:false},ctx);const removed=b.records.length===0,pointer=b.intake.tasks[0].feId;b=W.toggle(b.intake,b.records,{demandId:a.intake.demands[0].id,month:'2026-11',checked:true},ctx);console.log(JSON.stringify({removed,pointerSame:pointer===id,id:b.records[0].id===id,stage:b.records[0].stage,date:b.records[0].phaseDates.development.actualStart,history:b.records[0].history,count:b.records.length,withdrawn:b.intake.withdrawnFEs.length}))")
  self.assertEqual(x,{'removed':True,'pointerSame':True,'id':True,'stage':0,'date':'2026-11-04','history':[{'text':'开发中'}],'count':1,'withdrawn':0})
 def test_explicit_empty_review_withdraws_without_changing_development_stage(self):
  x=self.run_js("let a=base(),id=a.records[0].id;a.records[0].gate={pending:true,rd:true};a.records[0].flowRequests=[{id:'Q',status:'collecting',memberIds:[id]}];a=W.setReview(a.intake,a.records,{demandId:a.intake.demands[0].id,month:'2026-11',result:null},ctx);const held=a.intake.withdrawnFEs[0].record,removed=a.records.length===0;const decision=a.intake.tasks[0].review;a=W.setReview(a.intake,a.records,{demandId:a.intake.demands[0].id,month:'2026-11',result:'passed'},ctx);console.log(JSON.stringify({removed,decision,heldStage:held.stage,id:a.records[0].id===id,stage:a.records[0].stage,date:a.records[0].phaseDates.development.actualStart,pending:a.records[0].gate.pending,request:a.records[0].flowRequests[0].status,stopped:!!a.records[0].ratStops}))")
  self.assertEqual(x,{'removed':True,'decision':None,'heldStage':1,'id':True,'stage':1,'date':'2026-11-04','pending':False,'request':'cancelled','stopped':False})
 def test_manual_same_names_do_not_merge_fingerprints(self):
  x=self.run_js("let a=base(),first=a.records[0].id;a=W.save(a.intake,a.records,{content:'持续工作',modules:['系统'],month:'2026-11'},ctx);a=W.setReview(a.intake,a.records,{demandId:a.demandId,month:'2026-11',result:'passed'},ctx);console.log(JSON.stringify({demands:a.intake.demands.length,records:a.records.length,feIds:new Set(a.intake.tasks.map(t=>t.feId)).size,original:a.records.some(r=>r.id===first)}))")
  self.assertEqual(x,{'demands':2,'records':2,'feIds':2,'original':True})
 def test_explicit_rejection_stops_started_work_and_cancels_pending_requests(self):
  x=self.run_js("const a=base(),id=a.records[0].id;a.records[0].gate={pending:true,rd:true,qa:false};a.records[0].flowRequests=[{id:'Q',status:'collecting',memberIds:[id]}];let b=W.prepareMonth(a.intake,a.records,'2026-12',ctx);const old=JSON.stringify(b.intake.tasks[0]);b=W.toggle(b.intake,b.records,{demandId:b.intake.demands[0].id,month:'2026-12',checked:false},ctx);const r=b.records[0];console.log(JSON.stringify({records:b.records.length,id:r.id===id,stage:r.stage,oldMonth:JSON.stringify(b.intake.tasks[0])===old,months:r.ratMonths,pending:r.gate.pending,request:r.flowRequests[0].status,original:r.ratStops[0].stage,date:r.phaseDates.development.actualStart,decision:b.intake.tasks.find(t=>t.month==='2026-12').review.result,explicit:b.intake.tasks.find(t=>t.month==='2026-12').review.explicit}))")
  self.assertEqual(x,{'records':1,'id':True,'stage':9,'oldMonth':True,'months':['2026-11','2026-12'],'pending':False,'request':'cancelled','original':1,'date':'2026-11-04','decision':'rejected','explicit':True})
 def test_passing_again_restores_pre_stop_stage_but_not_cancelled_confirmations(self):
  x=self.run_js("let a=base(),id=a.records[0].id;a.records[0].stage=2;a.records[0].entered='2026-11-04';a.records[0].gate={pending:true,rd:true,qa:false};a.records[0].flowRequests=[{id:'Q',status:'collecting',memberIds:[id]}];a=W.toggle(a.intake,a.records,{demandId:a.intake.demands[0].id,month:'2026-11',checked:false},ctx);a=W.toggle(a.intake,a.records,{demandId:a.intake.demands[0].id,month:'2026-11',checked:true},ctx);const r=a.records[0];console.log(JSON.stringify({records:a.records.length,id:r.id===id,stage:r.stage,entered:r.entered,date:r.phaseDates.development.actualStart,pending:r.gate.pending,request:r.flowRequests[0].status,restored:r.ratStops[0].restoredAt===ctx.at}))")
  self.assertEqual(x,{'records':1,'id':True,'stage':2,'entered':'2026-11-04','date':'2026-11-04','pending':False,'request':'cancelled','restored':True})
 def test_repeated_stop_and_resume_uses_latest_stage_without_duplication(self):
  x=self.run_js("let a=base(),id=a.records[0].id;const decide=checked=>{a=W.toggle(a.intake,a.records,{demandId:a.intake.demands[0].id,month:'2026-11',checked},ctx);};decide(false);decide(false);decide(true);a.records[0].stage=3;decide(false);decide(true);console.log(JSON.stringify({records:a.records.length,id:a.records[0].id===id,stage:a.records[0].stage,stops:a.records[0].ratStops.map(s=>s.stage)}))")
  self.assertEqual(x,{'records':1,'id':True,'stage':3,'stops':[1,3]})
 def test_explicit_rejection_removes_unstarted_work_even_when_prior_month_passed(self):
  x=self.run_js("const a=base(),id=a.records[0].id;a.records[0].stage=0;let b=W.prepareMonth(a.intake,a.records,'2026-12',ctx);b=W.toggle(b.intake,b.records,{demandId:b.intake.demands[0].id,month:'2026-12',checked:false},ctx);console.log(JSON.stringify({records:b.records.length,withdrawn:b.intake.withdrawnFEs.map(x=>x.id),old:b.intake.tasks[0].review.result,new:b.intake.tasks.find(t=>t.month==='2026-12').review.result}))")
  self.assertEqual(x,{'records':0,'withdrawn':['FE-151'],'old':'passed','new':'rejected'})
 def test_existing_null_review_is_not_automatically_stopped_by_open_or_save(self):
  x=self.run_js("let a=base();a.intake.tasks[0].review=null;const d=a.intake.demands[0];a=W.save(a.intake,a.records,{demandId:d.id,revision:d.revision,content:d.content,modules:d.modules,source:d.source,month:'2026-11',owner:'乙',effort:'4'},ctx);console.log(JSON.stringify({records:a.records.length,stage:a.records[0].stage,review:a.intake.tasks[0].review}))")
  self.assertEqual(x,{'records':1,'stage':1,'review':None})
 def test_only_name_is_required_and_modules_do_not_create_more_tasks(self):
  x=self.run_js("let a=W.save(M.initial(),[],{content:'只有名称',month:'2026-11'},ctx);a=W.toggle(a.intake,a.records,{demandId:a.demandId,month:'2026-11',checked:true},ctx);const b=W.save(M.initial(),[],{content:'多模块工作',month:'2026-11',modules:['系统','规划']},ctx);console.log(JSON.stringify({nameOnly:a.intake.tasks.length,modules:a.records[0].modules,source:M.demandSource(a.intake.demands[0]),multi:b.intake.tasks.length,multiModules:b.intake.tasks[0].modules}))")
  self.assertEqual(x,{'nameOnly':1,'modules':[],'source':'','multi':1,'multiModules':['系统','规划']})
 def test_changed_people_and_modules_drive_resources_and_latest_approved_fe(self):
  x=self.run_js("const a=base();let b=W.prepareMonth(a.intake,a.records,'2026-12',ctx);const t=b.intake.tasks.find(t=>t.month==='2026-12');b=W.save(b.intake,b.records,{demandId:b.intake.demands[0].id,content:'持续工作',source:'内部迭代',modules:['控制'],month:'2026-12',assignments:[{id:t.id,allocations:[{key:t.allocations[0].key,owner:'乙',effort:'6',modules:['系统']}]}]},ctx);b=W.toggle(b.intake,b.records,{demandId:b.intake.demands[0].id,month:'2026-12',checked:true},ctx);const s=R.resources(b.intake,'2026-12'),entry=W.entries(b.intake,'2026-12')[0];console.log(JSON.stringify({people:s.people.map(p=>({name:p.name,days:p.days,modules:p.modules})),capacity:s.people[0].capacity,entryModules:entry.modules,feModules:b.records[0].modules,feOwner:b.records[0].owner,novemberOwner:b.intake.tasks[0].owner,novemberEffort:b.intake.tasks[0].effort}))")
  self.assertEqual(x,{'people':[{'name':'乙','days':6,'modules':['控制']}],'capacity':21,'entryModules':['控制'],'feModules':['控制'],'feOwner':'乙','novemberOwner':'甲','novemberEffort':'10'})
 def test_closed_work_is_excluded_while_stopped_work_is_not_invented_as_closed(self):
  x=self.run_js("const stages=[1,8,9,14],out=[];for(const stage of stages){const a=base();a.records[0].stage=stage;out.push({stage,eligible:W.eligible(a.intake,a.records,'2026-12').length});}console.log(JSON.stringify(out))")
  self.assertEqual(x,[{'stage':1,'eligible':1},{'stage':8,'eligible':0},{'stage':9,'eligible':1},{'stage':14,'eligible':0}])
 def test_save_failure_is_atomic_and_repeated_add_reuses_existing_identity(self):
  x=self.run_js("let a=base();const d=a.intake.demands[0],before=JSON.stringify(a);let error='';try{W.save(a.intake,a.records,{demandId:d.id,revision:d.revision-1,content:'旧页面',month:'2026-11'},ctx)}catch(e){error=e.message};const b=W.save(a.intake,a.records,{demandId:d.id,revision:d.revision,content:d.content,source:d.source,modules:d.modules,month:'2026-11'},ctx);console.log(JSON.stringify({error:!!error,unchanged:before===JSON.stringify(a),demands:b.intake.demands.length,tasks:b.intake.tasks.length,records:b.records.length,fe:b.records[0].id===a.records[0].id}))")
  self.assertEqual(x,{'error':True,'unchanged':True,'demands':1,'tasks':1,'records':1,'fe':True})

 def test_monthly_module_view_keeps_old_month_matching_its_resource_view(self):
  x=self.run_js("let a=base();a=W.prepareMonth(a.intake,a.records,'2026-12',ctx);const d=a.intake.demands[0],t=a.intake.tasks.find(t=>t.month==='2026-12');a=W.save(a.intake,a.records,{demandId:d.id,revision:d.revision,content:d.content,source:d.source,modules:['控制'],month:'2026-12',assignments:[{id:t.id,allocations:t.allocations.map(x=>({...x,owner:'乙',effort:'6'}))}]},ctx);console.log(JSON.stringify({nov:W.entries(a.intake,'2026-11')[0].modules,dec:W.entries(a.intake,'2026-12')[0].modules,resource:R.resources(a.intake,'2026-11','all').people[0].modules}))")
  self.assertEqual(x,{'nov':['系统','规划'],'dec':['控制'],'resource':['系统','规划']})

 def test_explicit_name_edit_updates_an_existing_link_without_resetting_execution(self):
  x=self.run_js("let a=base();delete a.records[0].ratDemandId;const d=a.intake.demands[0],id=a.records[0].id,before=JSON.stringify(a.records[0].history);a=W.save(a.intake,a.records,{demandId:d.id,revision:d.revision,content:'更正后的名称',modules:d.modules,source:d.source},ctx);console.log(JSON.stringify({same:a.records[0].id===id,name:a.records[0].title,stage:a.records[0].stage,actual:a.records[0].phaseDates.development.actualStart,history:JSON.stringify(a.records[0].history)===before}))")
  self.assertEqual(x,{'same':True,'name':'更正后的名称','stage':1,'actual':'2026-11-04','history':True})

if __name__=='__main__':unittest.main()
